import{_ as n,o as i,c as t,a5 as e}from"./chunks/framework.CsGesDJn.js";const d=JSON.parse('{"title":"E50-09 / DA-950 — Theo dõi đối tác Campaign","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/campaign-collaborators/spec.md","filePath":"feature/media-package-campaign/campaign-collaborators/spec.md"}'),c={name:"feature/media-package-campaign/campaign-collaborators/spec.md"};function h(o,a,r,g,l,p){return i(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="e50-09-da-950-—-theo-doi-đoi-tac-campaign" tabindex="-1">E50-09 / DA-950 — Theo dõi đối tác Campaign <a class="header-anchor" href="#e50-09-da-950-—-theo-doi-đoi-tac-campaign" aria-label="Permalink to &quot;E50-09 / DA-950 — Theo dõi đối tác Campaign&quot;">​</a></h1><h2 id="_1-nguon-va-pham-vi" tabindex="-1">1. Nguồn và phạm vi <a class="header-anchor" href="#_1-nguon-va-pham-vi" aria-label="Permalink to &quot;1. Nguồn và phạm vi&quot;">​</a></h2><p>Nguồn: master-plan DA-E50-09; BA 07 (third-party collaborator), BA 12 mục 6. Đối tác là đơn vị bên ngoài Agency, không phải thành viên Workspace. E50-08 quản lý danh bạ; E50-09 chỉ đọc danh bạ sẵn có, gán đối tác và theo dõi hợp tác. Không làm AI recommendation, booking, gửi liên hệ, thanh toán hoặc tự động publish.</p><h2 id="_2-luong" tabindex="-1">2. Luồng <a class="header-anchor" href="#_2-luong" aria-label="Permalink to &quot;2. Luồng&quot;">​</a></h2><p>Trong Workspace đã chốt Package, mở <strong>Đối tác chiến dịch</strong>. Khi Campaign tồn tại, Manager/Creator chọn đối tác của Agency, gán vào Campaign và cập nhật thủ công. Client xem danh sách/trạng thái, không được gán hoặc sửa. Owner được quản lý theo quyền Workspace; nếu chưa có membership, chủ Agency được quyền quản lý.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance criteria&quot;">​</a></h2><ul><li>AC1: Một cặp Campaign/đối tác có một bản ghi; gán lặp trả lại bản ghi cũ, không reset trạng thái. Đối tác chỉ thuộc cùng Agency với Workspace.</li><li>AC2: Các trạng thái CONTACTED, NEGOTIATING, CONFIRMED, LIVE; cho phép quay lại trạng thái trước theo BA 12, không áp đặt máy trạng thái một chiều.</li><li>AC3: Cùng đối tác ở Campaign khác có trạng thái độc lập. Lưu người/thời gian cập nhật; thay đổi hợp tác không sửa nội dung hoặc reset approvals Campaign.</li><li>AC4: Manager/Creator và Owner hợp lệ được ghi; Client chỉ đọc; người ngoài, membership hết hiệu lực, Workspace/Agency không hoạt động bị từ chối.</li><li>AC5: Danh sách phân trang, có tên/loại đối tác; giao diện có trạng thái loading, empty, retry và thông báo lỗi; chưa có Campaign thì không cho gán.</li><li>AC6: API Workspace kiểm tra Campaign và liên kết đúng scope. Cập nhật từ phiên cũ bị 409, không ghi đè âm thầm; dữ liệu đầu vào không hợp lệ bị 400.</li><li>AC7 (BA 2026-10-13, tích hợp DA-949): chỉ đối tác active được gán mới. Đối tác inactive đã liên kết vẫn hiển thị và được cập nhật hợp tác; gán lặp liên kết cũ giữ idempotency. Ghi dấu lần đầu sử dụng trong cùng transaction tạo liên kết; kiểm thử race với delete/deactivate. Xem <a href="./../partner-directory/spec.html">danh bạ</a>.</li></ul><h2 id="_4-du-lieu" tabindex="-1">4. Dữ liệu <a class="header-anchor" href="#_4-du-lieu" aria-label="Permalink to &quot;4. Dữ liệu&quot;">​</a></h2><p>Tái sử dụng PostgreSQL third_party_collaborators và campaign_collaborators, enum cooperation_status và UNIQUE(media_campaign_id, collaborator_id). Không init Mongo, không seed/xóa dữ liệu, không đổi schema nếu schema V2 đã có.</p><h2 id="_5-ngoai-le-va-quyet-đinh-trien-khai" tabindex="-1">5. Ngoại lệ và quyết định triển khai <a class="header-anchor" href="#_5-ngoai-le-va-quyet-đinh-trien-khai" aria-label="Permalink to &quot;5. Ngoại lệ và quyết định triển khai&quot;">​</a></h2><p>Workspace chưa có Package/Campaign trả danh sách rỗng có context, không lỗi 500. Không khóa theo Campaign status: đây là theo dõi vận hành độc lập với duyệt kế hoạch. Không bổ sung thao tác xóa liên kết ngoài AC. Danh bạ rỗng hướng dẫn hoàn thành E50-08. API legacy giữ hợp đồng cũ; endpoint Workspace mới yêu cầu expectedUpdatedAt.</p>',11)])])}const m=n(c,[["render",h]]);export{d as __pageData,m as default};
